/* Rockwater meeting reference. No remote processing, analytics or generated legal decisions. */
(() => {
'use strict';
const KEY='rwdef.case.v1', PREF='rwdef.preferences.v1';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const facts=[['allegation','Allegation'],['date','Date'],['time','Time'],['location','Location'],['amount','Amount allegedly consumed'],['drink','Type of drink'],['clocked','Clocked in?'],['shiftEnded','Shift ended?'],['serviceEnded','Service ended?'],['customers','Customers present?'],['employees','Employees present?'],['duties','Duties remaining?'],['lockup','Lock-up responsibility?'],['manager','Manager on duty?'],['authorised','Drink authorised?'],['authoriser','Who allegedly authorised?'],['evidence','Evidence relied upon'],['policy','Policy provision relied upon'],['gross','Gross misconduct alleged?'],['impairment','Actual impairment alleged?'],['potentialImpairment','Potential impairment alleged?'],['staffImpact','Actual staff impact alleged?'],['potentialImpact','Potential staff impact alleged?'],['safety','Safety issue alleged?'],['loss','Loss or damage alleged?']];
const statusOptions=['UNKNOWN','EMPLOYER ALLEGES','EMPLOYEE ACCEPTS','EMPLOYEE DISPUTES','SUPPORTED BY EVIDENCE','AGREED BY BOTH'];
const evidenceIssues=['Alcohol consumed?','During working hours?','Shift ended?','Active duties finished?','Lock-up responsibility?','Amount consumed?','Authorised?','Impairment?','Work performance affected?','Other employee affected?','Safety risk?','Previous comparable practice?','Applicable staff-drink rule?','Prior warnings?','Relevant mitigation?'];
const events=['Meeting started','Allegation stated','Evidence produced','New evidence','New allegation','Question asked','Answer given','Companion intervened','Adjournment requested','Adjournment granted','Adjournment refused','Mitigation raised','Procedural concern raised','Meeting adjourned','Meeting resumed','Outcome given','Meeting ended','Written outcome requested'];
const stages={Investigation:['Investigation identified','Evidence gathered','Employee interviewed if applicable','Relevant witnesses considered'],Notice:['Allegation provided','Possible consequences identified','Evidence provided','Reasonable preparation time'],Hearing:['Companion offered','Employer case explained','Employee allowed to respond','Questions allowed','Evidence challenged','Mitigation considered','Adjournment where appropriate'],Decision:['Evidence considered','Mitigation considered','Consistency considered','Appropriate sanction considered','Written outcome','Appeal information']};
const concernSentences={
'Evidence not provided in advance':'Please provide the evidence relied upon and allow me reasonable time to prepare my response.',
'Insufficient time to prepare':'I would like reasonable time to prepare a response to the allegation and evidence.',
'New evidence introduced':'I have only just been provided with this evidence. I would like reasonable time to consider it before responding.',
'New allegation introduced':'Please clarify this allegation and give me reasonable time to consider it and respond.',
'Not allowed to respond':'I would like the opportunity to respond to the allegation before a decision is made.',
'Interrupted / response not completed':'Please allow me to complete my response and have it recorded.',
'Mitigation not considered':'Please confirm that my explanation and mitigating circumstances will be considered before a decision is made.',
'Companion issue':'Please clarify the reason for the decision concerning my companion.',
'Adjournment request refused':'Please record my request for an adjournment and the decision to refuse it.',
'Apparent predetermination':'I would like it recorded that I am concerned the outcome may have been reached before my response has been fully considered.',
'Consistency concern':'Please confirm how consistency with comparable disciplinary cases has been considered.',
'Other':'I would like this procedural concern recorded.'};
function initial(){return {version:1,created:new Date().toISOString(),updated:null,facts:Object.fromEntries(facts.map(([k])=>[k,{value:k==='allegation'?'Drinking during working hours':'',status:k==='allegation'?'EMPLOYER ALLEGES':'UNKNOWN',source:k==='allegation'?'Employee-supplied project brief; invitation not supplied':'',share:false}])),evidence:evidenceIssues.map(issue=>({id:uid(),issue,employer:'',employee:'',evidence:'',source:'',status:'NOT PRODUCED',type:'Other',notes:''})),account:{recollection:'',uncertain:'',corrections:''},procedure:{},notes:'',log:[],questions:[],warnings:[{},{}],comparators:[],policies:[],timeline:[],mitigation:{},outcome:{},appeal:{},grievance:{},audit:[],attachments:[]};}
let storageError='', state=initial(), route='home', share=false, shareTab='reference', docFilter='', searchTerm='', responseTerm='', drawerId=null, openedOriginal=null;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.version===1)state={...initial(),...parsed};else storageError='Saved data uses an unsupported version. Export a backup before changing it.';}}catch(e){storageError='Browser storage is unavailable or saved data could not be read. Export your work regularly.';}
try{share=sessionStorage.getItem('rwdef.share')==='true';}catch{}
const docs=()=>window.RW_DOCUMENTS||[], quotes=()=>window.RW_QUOTES||[], legal=()=>window.RW_LEGAL||[], responses=()=>window.RW_RESPONSES||[];
function get(path){return path.split('.').reduce((o,k)=>o?.[k],state);}
function set(path,value){const keys=path.split('.');if(keys.some(k=>['__proto__','prototype','constructor'].includes(k)))return;let obj=state;keys.slice(0,-1).forEach((k,i)=>{if(!obj[k]||typeof obj[k]!=='object')obj[k]=/^\d+$/.test(keys[i+1])?[]:{};obj=obj[k];});obj[keys.at(-1)]=value;}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';const el=$('#saved');if(el)el.textContent='Saved on this device';}catch(e){storageError='Storage is full or unavailable. Export a backup now to protect your notes.';toast(storageError);const el=$('#saved');if(el)el.textContent='Not saved — export now';}}
function audit(action){state.audit.push({at:new Date().toISOString(),action});if(state.audit.length>800)state.audit=state.audit.slice(-800);}
const field=(path,label,placeholder='')=>`<label class="field">${esc(label)}<input data-field="${esc(path)}" value="${esc(get(path)||'')}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;
const area=(path,label,placeholder='')=>`<label class="field">${esc(label)}<textarea data-field="${esc(path)}" placeholder="${esc(placeholder)}">${esc(get(path)||'')}</textarea></label>`;
const select=(path,label,options)=>`<label class="field">${esc(label)}<select data-field="${esc(path)}">${options.map(o=>{const v=typeof o==='object'?o.value:o,l=typeof o==='object'?o.label:o;return `<option value="${esc(v)}" ${get(path)===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
const check=(path,label)=>`<label class="check"><input type="checkbox" data-field="${esc(path)}" ${get(path)?'checked':''}>${esc(label)}</label>`;
const button=(label,action,extra='',style='')=>`<button class="button ${style}" data-action="${action}" ${extra}>${label}</button>`;
const sourceButton=(topic,label='View source')=>`<button class="inline-source" data-action="topic" data-topic="${esc(topic)}">${esc(label)} ↗</button>`;
const tag=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const stamp=iso=>new Date(iso).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/London'});
const time=iso=>new Date(iso).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/London'});
const symbols={home:'◫',responses:'↳',facts:'≡',evidence:'▦',documents:'▤',alcohol:'◇',legal:'§',procedure:'☑',log:'◷',notes:'✎',mitigation:'⊞',settings:'⚙',outcome:'↗',appeal:'↶',timeline:'⋮',questions:'?',share:'▣'};
const navGroups=[['Meeting',[['home','Meeting dashboard'],['responses','Quick response'],['factcheck','Fact check'],['facts','Allegation & facts'],['evidence','Evidence matrix'],['questions','Questions'],['log','Meeting log']]],['Reference',[['alcohol','Alcohol & staff drinks'],['documents','Documents'],['legal','ACAS & law'],['procedure','Procedure & companion'],['compare','Compare provisions']]],['Preparation',[['account','My account'],['mitigation','Mitigation'],['sanctions','Sanctions'],['shift','Shift status'],['warnings','Previous warnings'],['timeline','Incident timeline'],['policy','Policy tracker'],['comparators','Comparable incidents'],['case','Case structure'],['challenge','Test my account'],['adjournment','Adjournment review'],['closing','Closing statement'],['notes','Private notes']]],['After the meeting',[['outcome','Outcome'],['appeal','Appeal'],['grievance','Grievance'],['summary','Meeting summary'],['settings','Backup & sources']]]];
const titles=Object.fromEntries(navGroups.flatMap(g=>g[1]));
function link(r,label,cls='button'){return `<a class="${cls}" href="#${r}">${esc(label)}</a>`;}
function head(title,sub,action=''){return `<header class="page-head"><div><div class="eyebrow">Meeting workspace / ${share?'Neutral reference':'Private preparation'}</div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div>${action||'<div class="head-meta">FACTS FIRST<br>Reference checked 7 October 2026</div>'}</header>`;}
function render(){
 try{sessionStorage.setItem('rwdef.share',String(share));}catch{}
 closeOverlay();document.body.classList.toggle('share',share);
 if(share){renderShare();return;}
 const content=page();
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="wordmark">ROCKWATER</div><small>Disciplinary meeting reference</small></div><nav class="nav" aria-label="Workspace">${navGroups.map(([group,items])=>`<div class="navlabel">${group}</div>${items.map(([id,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="ico" aria-hidden="true">${symbols[id]||'·'}</span>${label}</a>`).join('')}`).join('')}</nav><div class="sidebar-foot"><span class="dot"></span> PRIVATE WORKSPACE<br>Notes stay on this browser.<br><span id="offline-state">${navigator.onLine?'Checking offline readiness…':'Offline · local workspace'}</span></div></aside><div class="shell-main"><div class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="breadcrumb">Workspace &nbsp; / &nbsp; <strong>${esc(titles[route]||'Meeting')}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search">⌕ &nbsp; Search everything <span class="key">Ctrl K</span></button><span class="save-state" id="saved">${storageError?'Storage needs attention':'Saved on this device'}</span><button class="mode-switch" data-action="share">▣ &nbsp; Share screen</button></div></div><main class="workspace" id="main">${storageError?`<div class="notice danger">${esc(storageError)}</div>`:''}${content}</main></div></div><div class="floating no-print">${button('＋ Log event','event')}${button('Request adjournment','log','data-event="Adjournment requested"')}${button('Procedural concern','concern','','primary')}</div>`;
 updateOffline();
}
function page(){
 if(route==='home')return dashboard();
 if(route==='responses')return responsePage();
 if(route==='facts')return factPage();
 if(route==='evidence')return evidencePage();
 if(route==='documents')return documentPage();
 if(route==='alcohol')return alcoholPage();
 if(route==='legal')return legalPage();
 if(route==='procedure')return procedurePage();
 if(route==='log')return logPage();
 if(route==='notes')return head('Private notes','Autosaved on this browser. Hidden in share screen mode.')+`<section class="card">${area('notes','Meeting notes','Write freely. Nothing is sent to a server.')}<div class="row">${button('Save','save','','primary')}${button('Copy notes','copy-notes')}${button('Export TXT','export-txt')}${button('Print','print')}</div><p class="muted spaced">Browser storage is not encrypted. Make a backup before the hearing and use a device you trust.</p></section>`;
 if(route==='account')return head('My account','Recollection, uncertainty and corrections remain separate from evidence.')+`<div class="card">${tag('EMPLOYEE ACCOUNT','blue')}${area('account.recollection','My recollection','Enter only your own account. No incident facts have been assumed.')}${area('account.uncertain','What I cannot reliably recall')}${area('account.corrections','Corrections or clarification to previous answers')}<div class="notice">State what you remember accurately. If unsure, say so. A missing document does not establish that something did not happen.</div></div>`;
 if(route==='questions')return questionPage();
 if(route==='compare')return comparePage();
 if(route==='sanctions')return sanctionsPage();
 if(route==='factcheck')return factcheckPage();
 if(route==='summary')return summaryPage();
 if(route==='settings')return settingsPage();
 if(window.RW_WORKSPACES){const html=window.RW_WORKSPACES.render(route,state,{esc,field,area,select,check,sourceButton});if(html)return head(titles[route]||route,'Use entered facts and evidence. Unconfirmed matters stay unconfirmed.')+html;}
 return head('Workspace not found','Return to the meeting dashboard.')+link('home','Open dashboard');
}
function dashboard(){
 const quick=[['facts','Allegation'],['evidence','Evidence'],['account','My account'],['documents','Contract'],['documents','Handbook'],['legal','ACAS / law'],['questions','Questions'],['procedure','Procedure'],['mitigation','Mitigation'],['sanctions','Sanctions'],['log','Meeting log'],['settings','Sources']];
 const shortcuts=[['Alcohol during working hours','alcohol-hours','Handbook · conduct'],['Alcohol & gross misconduct','alcohol-gross-disciplinary','Handbook · disciplinary procedure'],['Post-shift staff drink','staff-drink','Conditions of Employment'],['Investigation & right to respond','investigation','Handbook · disciplinary procedure'],['Working hours & securing premises','security','Handbook / employment conditions'],['Companion & appeal','appeal','Handbook / official guidance']];
 return head('Your meeting, in focus.','Find the wording. Clarify the facts. Keep a clear record.',`<div class="row">${button('Start meeting','log','data-event="Meeting started"','primary')}</div>`)+`<div class="dashboard-grid"><div class="stack"><section class="card allegation-card"><div class="row spread"><div class="eyebrow">Current allegation</div>${tag('DETAILS TO ESTABLISH','amber')}</div><h2>${esc(state.facts.allegation.value||'Allegation not entered')}</h2><p class="muted">Employer allegation · incident details remain to be established</p><div class="fact-grid">${[['date','Date'],['time','Time'],['amount','Amount'],['evidence','Evidence'],['policy','Policy'],['shiftEnded','Shift status'],['impairment','Impairment'],['staffImpact','Impact']].map(([k,l])=>`<div class="fact"><label>${l}</label><strong>${esc(state.facts[k]?.value||'To establish')}</strong></div>`).join('')}</div><div class="row spaced">${link('facts','Clarify allegation →','button small')}${link('evidence','Open evidence matrix','button small ghost')}</div></section><section class="card response-card"><div class="eyebrow">Quick response</div><h2>What did they just say?</h2><p>A calm response, a factual question, and the source.</p><form id="quick-form" class="response-search"><input name="query" aria-label="What did they just say?" placeholder="Try ‘gross misconduct’ or ‘still working’"><button type="submit" aria-label="Find response">↗</button></form><div class="chips">${['Gross misconduct','Still working','CCTV','New evidence'].map(t=>`<button class="chip" data-action="response-search" data-term="${t}">${t}</button>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Go straight to</h2><span class="muted">One click away</span></div><div class="quicklinks">${quick.map(([r,l])=>link(r,`${symbols[r]||'·'}  ${l}`,'quicklink')).join('')}</div></section><div class="notice info">${tag('FACTS FIRST')} &nbsp; An allegation is not evidence. Unknown details remain unknown until you record the source and position.</div></div><div class="stack"><section class="card"><div class="card-head"><h2>Key provisions</h2>${tag('VERIFIED SOURCES')}</div>${shortcuts.map(([title,topic,subtitle])=>`<div class="source-row"><div><h3>${title}</h3><p>${subtitle}</p></div><button data-action="topic" data-topic="${topic}" aria-label="View ${title}">↗</button></div>`).join('')}</section><section class="card emergency"><div class="eyebrow">If new evidence appears</div><h2>Take time to review it.</h2><p>“I would like reasonable time to review this evidence before responding.”</p><div class="row">${button('Request adjournment','log','data-event="Adjournment requested"','small')}${sourceButton('acas-hearing','Source')}</div></section><section class="card"><div class="card-head"><h2>Meeting record</h2>${link('log','View log →','button small ghost')}</div>${state.log.length?`<div class="mini-log">${state.log.slice(-3).reverse().map(e=>`<div><time>${time(e.created)}</time><span>${esc(e.type)}</span></div>`).join('')}</div>`:'<p class="muted">No events recorded yet. Start the meeting or add your first event.</p>'}<div class="row spaced">${button('＋ Add event','event','','small')}</div></section></div></div>`;
}
function source(q){const d=docs().find(d=>d.id===q.doc);return {document:d?.title||q.document||q.doc||'Source',location:[q.section,q.page?`Page ${q.page}`:''].filter(Boolean).join(' · ')};}
function quoteCard(q,compact=false){const s=source(q);return `<article class="card"><div class="row spread">${tag('DOCUMENTED FACT')}<span class="muted">${esc(s.document)}</span></div><h3 class="spaced">${esc(q.title||q.section||'Exact wording')}</h3><blockquote class="quote ${compact?'compact':''}">“${esc(q.text)}”</blockquote><p class="quote-meta">${esc(s.location)} · Exact source text</p><div class="source-actions">${button('View source','source',`data-id="${esc(q.id)}"`,'small')}${button('Copy quote','copy-quote',`data-id="${esc(q.id)}"`,'small ghost')}</div></article>`;}
function findQuotes(topic){const terms=String(topic).toLowerCase().split(/\s+/).filter(Boolean);return quotes().map(q=>({q,score:terms.reduce((s,t)=>s+(q.id===topic?50:0)+(q.id?.includes(t)?8:0)+(String(q.topics).toLowerCase().includes(t)?5:0)+(String(q.title).toLowerCase().includes(t)?4:0)+(q.text.toLowerCase().includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.q);}
function responseSource(r){let ids=r.sources||[r.source,r.legalSource].filter(Boolean);if(!Array.isArray(ids))ids=[ids];return ids.map(id=>{if(typeof id==='object')id=id.id||id.topic||id.title;return sourceButton(id,'View source');}).join(' ');}
function responsePage(){return head('Quick response','No chatbot, no connection needed. Choose the claim you heard.')+`<input id="response-search" class="search-input" value="${esc(responseTerm)}" aria-label="Search quick responses" placeholder="Search a claim, e.g. intoxicated, clocked in, witness…"><div class="chips section-gap">${['','working','gross misconduct','evidence','warnings','resign'].map(t=>`<button class="chip" data-action="response-search" data-term="${t}">${t||'All responses'}</button>`).join('')}</div><div id="response-results" class="grid two section-gap">${responseResults()}</div>`;}
function responseResults(){const terms=responseTerm.toLowerCase().split(/\s+/).filter(Boolean);const result=responses().filter(r=>terms.every(t=>[r.claim,r.response,r.question,JSON.stringify(r.tags)].join(' ').toLowerCase().includes(t)));return result.map(r=>`<article class="card"><div class="eyebrow">They say</div><h2>${esc(r.claim)}</h2><div class="subtle-divider"></div><div class="eyebrow">Short response</div><p class="response-answer">${esc(r.response)}</p><div class="eyebrow spaced">Follow-up question</div><p>${esc(r.question)}</p><div class="source-actions">${responseSource(r)}${button('Log question','log',`data-event="Question asked" data-note="${esc(r.question)}"`,'small')}</div></article>`).join('')||'<p class="empty">No preset matches. Try one word, or search the source library.</p>';}
function factPage(){return head('Allegation & facts','Record the position and its source. Acceptance by one person does not mean agreement by both.')+`<div class="legend">${['DOCUMENTED FACT','EMPLOYER ALLEGATION','EMPLOYEE ACCOUNT','EVIDENCE','TO ESTABLISH','LEGAL / ACAS','ANALYSIS'].map(t=>tag(t)).join('')}</div><div class="card"><div class="notice info">Only “Agreed by both” enters the agreed-facts group. “Supported by evidence” requires an evidence reference; it does not resolve a dispute.</div>${facts.map(([k,label])=>`<div class="list-row"><div class="grid three">${field(`facts.${k}.value`,label,'Unknown / to establish')}${select(`facts.${k}.status`,'Position',statusOptions)}${field(`facts.${k}.source`,'Source / evidence reference','Who said this, or which record?')}</div>${check(`facts.${k}.share`,'Include this fact in neutral share view (status and source remain visible)')}</div>`).join('')}</div><section class="card section-gap"><h2>Recorded positions</h2><div class="grid three spaced">${factGroup('Agreed facts',['AGREED BY BOTH'])}${factGroup('Disputed facts',['EMPLOYEE DISPUTES'])}${factGroup('Unknown facts',['UNKNOWN'])}</div></section>`;}
function factGroup(title,statuses){return `<div><h3>${title}</h3><div class="muted spaced">${facts.filter(([k])=>statuses.includes(state.facts[k]?.status||'UNKNOWN')).map(([k,l])=>`<p><strong>${l}:</strong> ${esc(state.facts[k]?.value||'Unknown')}</p>`).join('')||'None recorded'}</div></div>`;}
function evidencePage(){return head('Evidence matrix','Keep the allegation, account and material actually produced separate.',button('＋ Add issue','add-evidence','','primary'))+`<div class="notice info">Use “Produced” only when material has actually been provided. A description of CCTV or a witness is not the CCTV or statement itself.</div><div class="card section-gap table-wrap"><table><thead><tr>${['Issue','Employer position','Employee position','Evidence / type','Source','Status','Private notes'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${state.evidence.map((r,i)=>`<tr><td>${field(`evidence.${i}.issue`,'Issue')}</td><td>${area(`evidence.${i}.employer`,'Employer position')}</td><td>${area(`evidence.${i}.employee`,'Employee position')}</td><td>${area(`evidence.${i}.evidence`,'Material produced')}${select(`evidence.${i}.type`,'Type',['Other','CCTV','Witness statement','Clock record','Till record','Receipt','Message','Email','Rota','Policy','Contract','Handbook','Employee admission'])}</td><td>${field(`evidence.${i}.source`,'Reference / location')}</td><td>${select(`evidence.${i}.status`,'Evidence status',['NOT PRODUCED','REQUESTED','PRODUCED','DISPUTED','NOT APPLICABLE'])}</td><td>${area(`evidence.${i}.notes`,'Private notes')}</td></tr>`).join('')}</tbody></table></div>`;}
function documentPage(){return head('Document library','Verified policy wording with section locators. Personal details are excluded from the public site.')+`<div class="tabs">${button('All provisions','doc-filter','data-doc=""',docFilter?'':'primary')}${docs().map(d=>button(esc(d.shortTitle||d.title),'doc-filter',`data-doc="${esc(d.id)}"`,docFilter===d.id?'primary':'')).join('')}</div><div class="row spaced">${button('Search full source text','search','','primary')}${link('settings','Open / attach original files')}</div><div class="grid two section-gap">${quotes().filter(q=>!docFilter||q.doc===docFilter).map(q=>quoteCard(q,true)).join('')}</div>${docFilter?fullDocument(docFilter):''}`;}
function fullDocument(id){const d=docs().find(d=>d.id===id);return d?`<section class="card section-gap"><h2>${esc(d.title)} · source text</h2><p class="muted spaced">${esc(d.note||d.redactionNote||d.locatorNote||'Paragraph locations are stable extraction locators, not Word page numbers. Formatting may differ from the original.')}</p>${(d.sections||[]).map(s=>`<details id="${esc(s.id)}"><summary>${esc(s.heading)}${s.page?' · page '+s.page:''}</summary><div class="fulltext">${esc(s.text)}</div></details>`).join('')}</section>`:'';}
function alcoholPage(){const qs=quotes().filter(q=>/alcohol|staff.drink|noncontractual|outside-work|complimentary|safety|gross-nonexhaustive/.test(q.id));return head('Alcohol & staff drinks','Read the provisions together, then apply them to the established facts.')+`<div class="notice info">${tag('ANALYSIS')} The post-shift benefit is discretionary and non-contractual. It does not permit drinking during working hours. Both gross-misconduct alcohol examples refer to possible effects; actual harm is not required by that wording.</div><div class="grid two section-gap">${qs.map(q=>quoteCard(q)).join('')}</div><section class="card section-gap"><h2>Friday–Sunday restriction</h2>${tag('SUPPLIED-DOCUMENT REVIEW')}<p class="spaced">No Friday–Sunday staff-drink restriction identified in the four supplied documents.</p><p class="muted spaced">This does not establish that no separate workplace policy, instruction or communicated rule exists.</p><p class="response-answer">Where is the Friday–Sunday restriction documented, and how was it communicated?</p>${link('policy','Record the rule and its source')}</section>`;}
function legalCard(l){return `<article class="card"><div class="row spread">${tag(l.kind||l.strength||'LEGAL / ACAS','blue')} ${tag(l.force||'REFERENCE')}<span class="muted">${esc(l.paragraph||l.locator||'')}</span></div><h2 class="spaced">${esc(l.title)}</h2><p class="spaced">${esc(l.summary)}</p>${l.note?`<p class="notice info spaced">${esc(l.note)}</p>`:''}${l.additionalUrl?`<a class="inline-source" href="${safeUrl(l.additionalUrl)}" target="_blank" rel="noopener noreferrer">Additional official source${l.additionalParagraph?' · '+esc(l.additionalParagraph):''} ↗</a>`:''}${l.quote?`<blockquote class="quote compact">“${esc(l.quote)}”</blockquote>`:''}<div class="source-actions">${button('View source','source',`data-id="${esc(l.id)}"`,'small')}<a class="button small ghost" href="${safeUrl(l.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></div><p class="quote-meta spaced">Checked ${esc(l.verified||'7 October 2026')} · ${esc(l.authority||'Official source')} · Summary unless marked as quotation</p></article>`;}
function legalPage(){return head('ACAS & UK law','Great Britain reference: rights, Code expectations and discretion are distinguished.')+`<div class="notice">Length of service may materially affect available statutory dismissal claims. This tool does not assume that ordinary unfair-dismissal protection applies. Use the official links to check changes after 7 October 2026.</div><div class="grid two section-gap">${legal().map(legalCard).join('')}</div>`;}
function procedurePage(){let idx=0;const confirmed=Object.values(state.procedure).filter(v=>v?.status==='CONFIRMED').length,total=Object.values(stages).flat().length;return head('Procedure & companion','A missing confirmation is not automatically a breach.')+`<div class="card"><div class="row spread"><h2>Procedural record</h2>${tag(`${confirmed} / ${total} CONFIRMED`)}</div><progress max="${total}" value="${confirmed}" class="section-gap" aria-label="Confirmed procedure steps"></progress><div class="source-actions">${sourceButton('disciplinary-rights','Rockwater procedure')}${sourceButton('acas-current','ACAS Code')}</div>${Object.entries(stages).map(([stage,items])=>`<details open><summary>${stage}</summary>${items.map(label=>{const k='p'+idx++;return `<div class="grid three">${select(`procedure.${k}.status`,label,['NOT CONFIRMED','CONFIRMED','DISPUTED','NOT APPLICABLE'])}${field(`procedure.${k}.evidence`,'What confirms / disputes this?')}${field(`procedure.${k}.response`,'Employer response')}</div>`;}).join('')}</details>`).join('')}</div><section class="card section-gap"><h2>Companion</h2><div class="notice info spaced">At a qualifying hearing, a reasonable request engages the statutory right to an eligible companion. A colleague, union official certified in writing by the union as trained or experienced, or an employed union official can qualify; there is no general automatic right to a solicitor.</div><div class="grid two spaced">${legal().filter(l=>/compan|postpon/.test(l.id+' '+l.title.toLowerCase())).map(legalCard).join('')}</div>${sourceButton('companion','Handbook wording')}${field('companion.name','Companion name / role')}${field('companion.availability','Availability / any alternative date proposed')}</section>`;}
function logPage(){return head('Meeting log','Timestamped in Europe/London. Editing keeps the original creation time.',button('＋ Add event','event','','primary'))+`<div class="chips">${events.map(e=>`<button class="chip" data-action="log" data-event="${e}">${e}</button>`).join('')}</div><section class="card section-gap">${state.log.length?state.log.slice().reverse().map(e=>`<article class="event"><time>${stamp(e.created)}${e.edited?' · edited '+stamp(e.edited):''}</time><h3>${esc(e.type)}</h3><p class="fulltext">${esc(e.note)}</p><div class="row spaced">${tag(e.status||'EMPLOYEE RECORD','blue')}${button('Edit','edit-event',`data-id="${e.id}"`,'small ghost')}</div></article>`).join(''):'<div class="empty">Your meeting record starts here.<br>Add an event when something happens.</div>'}</section>`;}
function questionPage(){const list=['What precise incident, date and time are alleged?','What evidence supports this allegation?','Which policy provision is relied upon?','What duties are said to have remained?','What potential performance, employee or safety effect is alleged?','When and how was any separate staff-drink rule communicated?','What mitigating circumstances have been considered?','What lesser sanctions were considered and why were they rejected?'];return head('Questions','Calm clarification. Record the answer without converting it into a verified fact.')+`<div class="grid two">${list.map(q=>`<section class="card"><p>${esc(q)}</p><div class="source-actions">${button('Ask / record','log',`data-event="Question asked" data-note="${esc(q)}"`,'small')}${button('Add to checklist','add-question',`data-question="${esc(q)}"`,'small ghost')}</div></section>`).join('')}</div><section class="card section-gap"><div class="row spread"><h2>My questions</h2>${button('＋ Add question','add-question')}</div>${state.questions.map((q,i)=>`<div class="list-row">${field(`questions.${i}.question`,'Question')}${area(`questions.${i}.answer`,'Answer given / source')}${check(`questions.${i}.answered`,'Answered')}</div>`).join('')||'<p class="empty">Add the questions you want to track.</p>'}</section>`;}
function comparePage(){const chosen=get('compare.ids')||[];return head('Compare provisions','Relevant provisions requiring application to the established facts.')+`<section class="card"><h2>Choose provisions</h2><div class="grid two spaced">${quotes().map(q=>`<label class="check"><input type="checkbox" data-compare="${esc(q.id)}" ${chosen.includes(q.id)?'checked':''}>${esc(q.title||q.section)} · ${esc(source(q).document)}</label>`).join('')}</div>${button('Staff drink / alcohol preset','compare-preset','','primary')}</section><div class="grid two section-gap">${quotes().filter(q=>chosen.includes(q.id)).map(q=>quoteCard(q)).join('')}</div><section class="card section-gap">${area('compare.observations','Private comparison notes','Explain how the wording relates to established facts. These provisions are not automatically contradictions.')}</section>`;}
function sanctionsPage(){const options=['No action','Informal action','First written warning','Final written warning','Action short of dismissal','Dismissal'];return head('Sanctions & proportionality','Possible outcomes for comparison. This tool does not predict a decision.')+`<div class="grid two">${quotes().filter(q=>/sanction|warning|dismissal|serious-progression|informal/.test(q.id)).map(q=>quoteCard(q,true)).join('')}</div><section class="card section-gap"><div class="notice info">The handbook allows entry at later stages in serious cases and says dismissal for a first gross-misconduct offence may occur. Dismissal is not described as mandatory.</div><div class="grid two spaced">${select('sanctions.proposed','Proposed outcome',['Unknown',...options])}${field('sanctions.reason','Employer’s stated reason')}</div>${area('sanctions.comparison','Alternatives considered / reasons given')}<div class="chips">${options.map(o=>`<span class="chip">${o}</span>`).join('')}</div><div class="longtext spaced">What factors determine the proposed sanction?
How were mitigating circumstances weighed?
Were comparable cases considered?
What lesser sanctions were considered, and if rejected, why?</div></section>`;}
function factcheckPage(){const checks=[['Actual harm must occur before alcohol can be gross misconduct.','NOT SUPPORTED','The examples refer to possible work-performance effects or employee impact. Both clauses and other potentially relevant gross-misconduct provisions must be considered.','alcohol-gross'],['A post-shift drink is an unconditional contractual right.','NOT SUPPORTED','The Conditions of Employment describe the benefit as non-contractual and subject to duty-manager discretion, directly after the working shift.','staff-drink'],['There is no Friday–Sunday rule.','NOT ESTABLISHED','No restriction was identified in supplied documents. A separate instruction or policy could exist. Ask for its source and communication.','staff-drink'],['Clocking out alone proves all work had ended.','NOT ESTABLISHED','Consider the actual duties, hours, responsibility to secure premises, permission and evidence. No single recorded fact automatically resolves the issue.','working-hours'],['Dismissal is automatic for a first gross-misconduct allegation.','NOT SUPPORTED','The handbook says dismissal for a first offence may occur. The allegation still requires investigation and consideration of the facts and mitigation.','sanction'],['Any departure from ACAS automatically makes dismissal unlawful.','NOT SUPPORTED','The Code has a specific statutory role. A departure does not, by itself, establish legal liability or eligibility to bring a claim.','acas-status'],['An unsupported allegation establishes that the incident happened.','NOT SUPPORTED','Accounts and statements can be evidence. Distinguish the source, what was actually produced and what remains disputed; a bare allegation does not establish the incident.','investigation']];return head('Fact check','Deterministic checks against the source wording. No automated legal finding.')+`<div class="grid two">${checks.map(([claim,status,summary,topic])=>`<article class="card">${tag(status,'amber')}<h2 class="spaced">${claim}</h2><p class="muted spaced">${summary}</p>${sourceButton(topic)}</article>`).join('')}</div><section class="card section-gap"><h2>Check a new claim</h2>${field('factcheck.claim','Claim to test')}${area('factcheck.source','Exact source and wording')}${select('factcheck.status','Your assessment',['UNASSESSED','SUPPORTED','PARTLY SUPPORTED','NOT SUPPORTED','UNKNOWN'])}${area('factcheck.notes','Reason / missing information')}</section>`;}
function reportText(){return ['MEETING FACT SUMMARY','Generated '+stamp(new Date()),'','ALLEGATION',state.facts.allegation.value||'Not entered','','RECORDED FACTS',...facts.filter(([k])=>state.facts[k]?.value).map(([k,l])=>`${l}: ${state.facts[k].value} [${state.facts[k].status}] — source: ${state.facts[k].source||'not entered'}`),'','EVIDENCE PRESENTED',...state.evidence.filter(e=>e.status==='PRODUCED').map(e=>`${e.issue}: ${e.evidence||'description not entered'} — ${e.source||'source not entered'}`),'','EMPLOYEE RESPONSE',state.account.recollection||'Not entered','','UNANSWERED QUESTIONS',...state.questions.filter(q=>!q.answered).map(q=>q.question||''),'','MITIGATION',...Object.entries(state.mitigation||{}).filter(([,v])=>v?.confirmed).map(([k,v])=>`${v.label||k}: ${v.evidence||'Evidence not entered'}${v.raised?' — raised':''}`),'','PROCEDURAL RECORD',...Object.entries(state.procedure).map(([k,v])=>`${Object.values(stages).flat()[+k.slice(1)]||k}: ${v.status||'NOT CONFIRMED'} — ${v.evidence||''} ${v.response?'Employer response: '+v.response:''}`),'','MEETING LOG',...state.log.map(e=>`${stamp(e.created)} | ${e.type} | ${e.note||''}`),'','OUTCOME',...Object.entries(state.outcome||{}).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`)].join('\n');}
function summaryPage(){return head('Meeting fact summary','Compiled from entered information. Review and correct it before sharing.')+`<section class="card"><div class="row no-print">${button('Copy summary','copy','data-copyid="summary-text"','primary')}${button('Export TXT','export-summary')}${button('Print / Save PDF','print')}</div><pre class="longtext" id="summary-text">${esc(reportText())}</pre></section>`;}
function settingsPage(){return head('Backup & sources','Local case data, original files and offline readiness.')+`<div class="grid two"><section class="card"><h2>Protect your meeting record</h2><p class="muted spaced">Your case is saved only in this browser profile. Backups contain private case data and are not encrypted. Store them somewhere private.</p><div class="row spaced">${button('Export JSON backup','export-json','','primary')}${button('Export TXT','export-txt')}${button('Import backup','import-json')}</div><input type="file" id="backup-file" accept=".json,application/json" hidden><p class="muted spaced">Attached original files are stored separately on this device and are not included in JSON backups. Keep your source files.</p></section><section class="card"><h2>Offline readiness</h2><p class="muted spaced" id="cache-status">Checking…</p><div class="row spaced">${button('Check cached files','offline-check')}${link('documents','Browse cached reference')}</div><p class="muted spaced">Open the site once while connected. The app, source extracts and legal summaries work offline; external official links need a connection.</p></section><section class="card"><h2>Original documents</h2><p class="muted spaced">Attach the supplied PDFs and handbook here to open them locally. Files stay in this browser’s IndexedDB and are never uploaded. Exact extracted policy text is already included.</p><div class="row spaced">${button('Attach original file','attach','','primary')}</div><input type="file" id="original-file" accept=".pdf,.docx,.txt,.png,.jpg,.jpeg" hidden>${state.attachments.map(a=>`<div class="source-row"><div><h3>${esc(a.name)}</h3><p>${Math.round(a.size/1024)} KB · local only</p></div>${button('Open','open-attachment',`data-id="${a.id}"`,'small')}</div>`).join('')}</section><section class="card"><h2>Source integrity</h2><p class="muted spaced">Four supplied employment documents were inspected. PDF page locators refer to source pages. Handbook paragraphs use extraction locators; they are not invented page numbers. Personal contact, pay, signature and e-signing records are excluded from public reference files.</p><div class="row spaced"><a class="button small" href="SOURCE-AUDIT.md" target="_blank">Source audit</a><a class="button small" href="ASSUMPTIONS-AUDIT.md" target="_blank">Assumptions audit</a><a class="button small" href="disciplinary-quick-reference.html" target="_blank">Emergency quick reference</a></div></section><section class="card"><h2>How the workspace handles privacy</h2><p class="muted spaced">No accounts, analytics, telemetry, microphone, recording or note uploads. The website itself is public. Share mode removes private views from the page; it is not an access password. Your browser storage is not encrypted and other software with access to this browser profile may read it.</p><p class="muted spaced">Use the downloaded local launcher if you prefer a separate localhost browser origin. Device backups, browser extensions and synchronised folders are outside this tool’s control.</p></section><section class="card danger-zone"><h2>Clear case data</h2><p class="muted spaced">Removes this workspace’s saved case, audit and attached originals from this browser. Export a backup first.</p><div class="row spaced">${button('Clear local case data','clear-data','','danger')}</div></section></div><details class="card section-gap"><summary>Local audit trail</summary>${state.audit.slice(-80).reverse().map(a=>`<p class="muted">${stamp(a.at)} · ${esc(a.action)}</p>`).join('')||'<p class="muted">No actions recorded.</p>'}</details>`;}
function renderShare(){const safeFacts=facts.filter(([k])=>state.facts[k]?.share&&state.facts[k]?.value);$('#app').innerHTML=`<div class="share-banner"><strong>▣ &nbsp; NEUTRAL SHARE VIEW · private preparation hidden</strong>${button('Return to private workspace','private','','small no-print')}</div><div class="share-shell"><header class="share-head"><div><div class="wordmark">ROCKWATER</div><p class="muted spaced">Disciplinary meeting reference</p></div><div class="row no-print">${button('Find a provision','search')}${button('Print neutral view','print')}</div></header><div class="tabs share-tabs no-print">${['reference','law','facts'].map(t=>button(t==='reference'?'Document wording':t==='law'?'Official guidance':'Selected meeting facts','share-tab',`data-tab="${t}"`,shareTab===t?'primary':'')).join('')}</div><main id="main" class="share-main">${shareTab==='law'?`<div class="grid two">${legal().map(legalCard).join('')}</div>`:shareTab==='facts'?`<section class="card"><h1>Selected meeting facts</h1><p class="muted spaced">Explicitly selected for display. Status and source are retained; inclusion does not establish agreement.</p>${safeFacts.map(([k,l])=>`<div class="source-row"><div><h3>${l}</h3><p class="fulltext">${esc(state.facts[k].value)}</p><p>Source: ${esc(state.facts[k].source||'Not recorded')}</p></div>${tag(state.facts[k].status,'blue')}</div>`).join('')||'<p class="empty">No meeting facts have been selected for display.</p>'}</section>`:`<div class="notice info">Exact wording from supplied documents. These provisions need to be applied to the established facts.</div><div class="grid two section-gap">${quotes().map(q=>quoteCard(q,true)).join('')}</div>`}</main></div>`;}
function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
function closeOverlay(){const el=$('#overlay');if(el)el.innerHTML='';drawerId=null;}
function overlay(html,drawer=false){$('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close"></div><section role="dialog" aria-modal="true" aria-label="${drawer?'Source reference':'Workspace dialog'}" class="${drawer?'drawer':'modal'}"><div class="modal-head"><span class="eyebrow">${share?'Neutral reference':'Meeting reference'}</span><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${html}</section>`;setTimeout(()=>$('#overlay input, #overlay textarea, #overlay button')?.focus(),30);}
function showSource(id){const q=quotes().find(q=>q.id===id),l=legal().find(l=>l.id===id);if(!q&&!l){openSearch(id);return;}drawerId=id;
 if(l){overlay(`<div class="row">${tag(l.kind||'LEGAL / ACAS','blue')} ${tag(l.force||'REFERENCE')}</div><h1 class="spaced">${esc(l.title)}</h1><p class="longtext spaced">${esc(l.summary)}</p>${l.note?`<p class="notice info spaced">${esc(l.note)}</p>`:''}${l.additionalUrl?`<a class="inline-source" href="${safeUrl(l.additionalUrl)}" target="_blank" rel="noopener noreferrer">Additional official source ↗</a>`:''}${l.quote?`<blockquote class="quote">“${esc(l.quote)}”</blockquote>`:''}<div class="card section-gap"><p class="quote-meta">${esc(l.paragraph||l.locator||'')}<br>Verified ${esc(l.verified||'7 October 2026')}<br>Source type: official legal / procedural reference</p><a class="button spaced" target="_blank" rel="noopener noreferrer" href="${safeUrl(l.url)}">Open official source ↗</a></div><div class="row spaced">${!share?button('Share this source','share-source',`data-id="${esc(id)}"`,'primary'):''}${button('Copy reference','copy-quote',`data-id="${esc(id)}"`)}</div>`,true);return;}
 const s=source(q),d=docs().find(d=>d.id===q.doc);let section=(d?.sections||[]).find(s=>s.id===q.sectionId||s.heading===q.section||s.text?.includes(q.text));
 overlay(`${tag('DOCUMENTED FACT')}<h1 class="spaced">${esc(q.title||q.section)}</h1><p class="muted spaced">${esc(s.document)}<br>${esc(s.location)}</p><blockquote class="quote">“${esc(q.text)}”</blockquote><p class="quote-meta">Exact wording · primary employment document</p><div class="row spaced">${button('Copy quote','copy-quote',`data-id="${esc(id)}"`)}${!share?button('Share this source','share-source',`data-id="${esc(id)}"`,'primary'):''}</div><details class="source-context" open><summary>Surrounding source context</summary><div class="fulltext">${esc(q.context||section?.text||q.text)}</div></details><p class="notice info spaced">${esc(q.note||'A source provision does not establish what occurred in the incident. Read it alongside the evidence and other relevant provisions.')}</p>`,true);
}
function topic(text){const aliases={'alcohol-rule':'alcohol-hours','lock-up':'security','working-hours':'hours','sanction':'sanctions','acas-status':'law-code-status','disciplinary-rights':'rights','mitigating circumstances':'mitigation','summary dismissal':'summary-dismissal','preparation':'acas-notice','grievance':'grievance-initiate','line manager':'grievance-alternate-manager','working hours':'hours','securing':'security','written warning':'warnings-first','action short':'sanctions','staff drink':'staff-drink','summary-dismissal':'sanctions'};text=aliases[text]||text;const exact=quotes().find(q=>q.id===text)||legal().find(l=>l.id===text);if(exact){showSource(exact.id);return;}const qs=findQuotes(text);if(qs.length){showSource(qs[0].id);return;}const ls=legal().find(l=>(l.title+' '+l.id).toLowerCase().includes(text.toLowerCase()));if(ls)showSource(ls.id);else openSearch(text);}
function openSearch(term=''){searchTerm=term;overlay(`<h1>Find the exact wording.</h1><p class="muted spaced">${share?'Neutral document and official guidance search.':'Search source text, provisions and official guidance. Ctrl K anywhere.'}</p><input id="global-search" class="search-input section-gap" placeholder="Alcohol, working hours, appeal…" aria-label="Search source library" value="${esc(term)}"><div id="global-results" class="search-results">${searchResults(term)}</div>`);setTimeout(()=>$('#global-search')?.focus(),30);}
function searchResults(term){if(!term.trim())return `<div class="chips">${['alcohol','staff drinks','investigation','mitigation','working hours','appeal'].map(t=>`<button class="chip" data-action="search-term" data-term="${t}">${t}</button>`).join('')}</div><p class="empty">Search ${quotes().length} verified provisions and ${legal().length} official reference cards, plus the extracted document text.</p>`;
 const terms=term.toLowerCase().split(/\s+/).filter(Boolean),match=t=>terms.every(w=>t.toLowerCase().includes(w));
 const qs=quotes().filter(q=>match([q.id,q.title,q.section,q.text,q.topics].join(' '))).slice(0,30),ls=legal().filter(l=>match([l.title,l.summary,l.id].join(' '))).slice(0,15),ss=docs().flatMap(d=>(d.sections||[]).filter(s=>match(s.heading+' '+s.text)).slice(0,10).map(s=>({d,s}))).slice(0,25);
 return `${qs.length+ls.length+ss.length?`<p class="muted">${qs.length+ls.length+ss.length} matching entries${ss.length===25?' · narrow the search for more':''}</p>`:'<p class="empty">No exact matches. Try a shorter word or phrase.</p>'}${qs.map(q=>`<article class="result">${tag('DOCUMENT')}<h3 class="spaced">${esc(q.title||q.section)}</h3><p>${esc(q.text.slice(0,240))}${q.text.length>240?'…':''}</p>${button('View source','source',`data-id="${esc(q.id)}"`,'small spaced')}</article>`).join('')}${ls.map(l=>`<article class="result">${tag('LEGAL / ACAS','blue')}<h3 class="spaced">${esc(l.title)}</h3><p>${esc(l.summary)}</p>${button('View source','source',`data-id="${esc(l.id)}"`,'small spaced')}</article>`).join('')}${ss.map(({d,s})=>`<article class="result">${tag('FULL SOURCE TEXT')}<h3 class="spaced">${esc(d.title)} · ${esc(s.heading)}</h3><p>${esc(snippet(s.text,terms[0]))}</p>${button('Read section','section',`data-doc="${esc(d.id)}" data-section="${esc(s.id)}"`,'small spaced')}</article>`).join('')}`;
}
function snippet(text,term){const at=text.toLowerCase().indexOf(term),start=Math.max(0,at-80);return (start?'…':'')+text.slice(start,start+300)+(text.length>start+300?'…':'');}
function eventDialog(type='',note='',id=null){const e=id?state.log.find(e=>e.id===id):null;overlay(`<h1>${e?'Edit meeting event':'Record a meeting event'}</h1><p class="muted spaced">${e?'Created '+stamp(e.created)+' · original timestamp retained':'Timestamped when saved. A private employee record, not an agreed minute.'}</p><label class="field spaced">Event<select id="event-type">${events.map(t=>`<option ${t===(e?.type||type)?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Note / reason / exact response<textarea id="event-note">${esc(e?.note||note)}</textarea></label><div class="row">${button(e?'Save changes':'Add to meeting log','save-event',id?`data-id="${id}"`:'','primary')}${button('Cancel','close')}</div>`);}
function concerns(){overlay(`<h1>Record a procedural concern</h1><p class="muted spaced">Choose a concern to see a calm sentence and the relevant reference.</p><div class="chips section-gap">${Object.keys(concernSentences).map(k=>`<button class="chip" data-action="concern-item" data-concern="${esc(k)}">${esc(k)}</button>`).join('')}</div>`);}
function exportFile(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied');}catch{overlay(`<h2>Copy this text</h2><textarea class="search-input section-gap" id="copy-fallback">${esc(text)}</textarea>`);$('#copy-fallback').select();}}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4000);}
function attachDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('rwdef.files.v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbOp(mode,fn){const db=await attachDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode);let result;const request=fn(tx.objectStore('files'));if(request)request.onsuccess=()=>result=request.result;tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function checkOffline(){try{const reg=await navigator.serviceWorker?.getRegistration();if(reg?.active){const keys=await caches.keys();const key=keys.find(k=>k.startsWith('rwdef-'));if(key){const cache=await caches.open(key);const items=await cache.keys();return items.length>=9?'Ready · app and references saved for offline use.':'Cache incomplete · keep this tab online until ready.';}}return 'Not ready yet. Open over HTTPS or localhost and allow a few seconds for caching.';}catch{return 'Offline cache unavailable in this browser. Keep a local copy as backup.';}}
async function updateOffline(){const text=await checkOffline();if($('#offline-state'))$('#offline-state').textContent=text.startsWith('Ready')?'Offline reference ready':navigator.onLine?'Online · offline setup pending':'Offline';if($('#cache-status'))$('#cache-status').textContent=text;}
function validBackup(b){if(!b||b.version!==1||!b.facts||typeof b.facts!=='object'||!Array.isArray(b.log)||!Array.isArray(b.evidence))throw Error('Not a supported Rockwater case backup.');const rejectKeys=o=>{if(!o||typeof o!=='object')return;for(const k of Object.keys(o)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Unsafe backup key.');rejectKeys(o[k]);}};rejectKeys(b);for(const key of ['account','procedure','mitigation','outcome','appeal','grievance'])if(b[key]&&(typeof b[key]!=='object'||Array.isArray(b[key])))throw Error('Invalid section: '+key);for(const key of ['evidence','questions','warnings','comparators','policies','timeline','audit','attachments'])if(Array.isArray(b[key])&&b[key].some(row=>!row||typeof row!=='object'||Array.isArray(row)))throw Error('Invalid row in '+key);for(const [k]of facts){if(!b.facts[k]||typeof b.facts[k].value!=='string'||!statusOptions.includes(b.facts[k].status))throw Error('Invalid fact record: '+k);}for(const e of b.log)if(typeof e.type!=='string'||typeof e.created!=='string'||!Number.isFinite(Date.parse(e.created)))throw Error('Invalid event record.');for(const key of ['questions','warnings','comparators','policies','timeline','audit','attachments'])if(b[key]&&!Array.isArray(b[key]))throw Error('Invalid collection: '+key);return {...initial(),...b,attachments:state.attachments};}
async function action(el){const a=el.dataset.action;
 if(share&&!['private','share-tab','search','search-term','source','topic','section','copy-quote','close','print'].includes(a))return;
 if(a==='menu')$('#sidebar').classList.toggle('open');
 else if(a==='close')closeOverlay();
 else if(a==='refresh'){save();render();toast('Draft updated from entered information');}
 else if(a==='save'){save();toast(storageError||'Saved on this device');}
 else if(a==='share'||a==='share-source'){const id=el.dataset.id;share=true;shareTab='reference';render();if(id)showSource(id);}
 else if(a==='private'){share=false;render();}
 else if(a==='share-tab'){shareTab=el.dataset.tab;render();}
 else if(a==='search')openSearch();
 else if(a==='search-term'){const t=el.dataset.term;$('#global-search').value=t;$('#global-results').innerHTML=searchResults(t);}
 else if(a==='source')showSource(el.dataset.id);
 else if(a==='topic')topic(el.dataset.topic);
 else if(a==='section'){const d=docs().find(d=>d.id===el.dataset.doc),s=d?.sections.find(s=>s.id===el.dataset.section);if(s)overlay(`<h1>${esc(s.heading)}</h1><p class="muted spaced">${esc(d.title)} ${s.page?'· Page '+s.page:''}</p><div class="fulltext section-gap">${esc(s.text)}</div>`,true);}
 else if(a==='copy-quote'){const q=quotes().find(q=>q.id===el.dataset.id),l=legal().find(l=>l.id===el.dataset.id);if(q)copy('“'+q.text+'”\n'+source(q).document+' · '+source(q).location);else if(l)copy(l.title+'\nSummary: '+l.summary+'\n'+l.url+'\nVerified '+l.verified);}
 else if(a==='copy')copy(document.getElementById(el.dataset.copyid)?.textContent||'');
 else if(a==='copy-notes')copy(state.notes);
 else if(a==='print'){closeOverlay();window.print();}
 else if(a==='doc-filter'){docFilter=el.dataset.doc;render();}
 else if(a==='response-search'){responseTerm=el.dataset.term;if(route==='responses')render();else location.hash='responses';}
 else if(a==='log')eventDialog(el.dataset.event,el.dataset.note);
 else if(a==='event')eventDialog();
 else if(a==='edit-event')eventDialog('','',el.dataset.id);
 else if(a==='save-event'){const note=$('#event-note').value,type=$('#event-type').value,now=new Date().toISOString(),id=el.dataset.id;if(id){const e=state.log.find(e=>e.id===id);e.note=note;e.type=type;e.edited=now;audit('Edited event '+id+'; original timestamp retained');}else{state.log.push({id:uid(),created:now,type,note,status:'EMPLOYEE RECORD'});audit('Added event: '+type);}save();render();toast('Event recorded');}
 else if(a==='concern')concerns();
 else if(a==='concern-item'){const c=el.dataset.concern;overlay(`<h1>${esc(c)}</h1><div class="eyebrow spaced">Suggested sentence</div><p class="response-answer">${esc(concernSentences[c])}</p>${sourceButton(c.includes('Companion')?'companion':c.includes('Mitigation')?'mitigation':'acas-hearing')}<div class="row spaced">${button('Timestamp concern','log',`data-event="Procedural concern raised" data-note="${esc(c+': '+concernSentences[c])}"`,'primary')}${button('Back','concern')}</div>`);}
 else if(a==='add-evidence'){state.evidence.push({id:uid(),issue:'',employer:'',employee:'',evidence:'',source:'',status:'NOT PRODUCED',type:'Other',notes:''});save();render();}
 else if(a==='add-question'){state.questions.push({question:el.dataset.question||'',answer:'',answered:false});save();if(route==='questions')render();toast('Question added');}
 else if(a==='add-row'){const collection=el.dataset.collection;if(!['comparators','policies','timeline','warnings','questions'].includes(collection))return;let template={};try{template=JSON.parse(el.dataset.template||'{}');}catch{}state[collection]||=[];state[collection].push(template);save();render();}
 else if(a==='compare-preset'){state.compare={...state.compare,ids:quotes().filter(q=>/staff-drink|alcohol-hours|alcohol-gross/.test(q.id)).map(q=>q.id)};save();render();}
 else if(a==='export-json'){save();exportFile('rockwater-case-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');}
 else if(a==='export-txt')exportFile('rockwater-private-notes.txt',reportText()+'\n\nPRIVATE NOTES\n'+state.notes);
 else if(a==='export-summary')exportFile('rockwater-meeting-summary.txt',reportText());
 else if(a==='import-json')$('#backup-file').click();
 else if(a==='confirm-import'){state=validBackup(action.pendingImport);action.pendingImport=null;audit('Imported case backup');save();render();toast('Backup imported');}
 else if(a==='attach')$('#original-file').click();
 else if(a==='open-attachment'){try{const f=await dbOp('readonly',s=>s.get(el.dataset.id));if(!f)throw Error('File not available in this browser. Reattach the original.');if(openedOriginal)URL.revokeObjectURL(openedOriginal);openedOriginal=URL.createObjectURL(f.file);const tab=window.open(openedOriginal,'_blank','noopener,noreferrer');if(!tab)toast('Original opened or downloaded. Allow pop-ups if needed.');}catch(e){toast(e.message);}}
 else if(a==='offline-check'){await updateOffline();toast(await checkOffline());}
 else if(a==='clear-data')overlay(`<h1>Clear this local workspace?</h1><p class="muted spaced">This removes saved case data, notes, audit history and attached originals from this browser. The reference library remains available.</p><label class="field spaced">Type CLEAR to confirm<input id="clear-confirm" autocomplete="off"></label><div class="row">${button('Export backup first','export-json')}${button('Clear case data','confirm-clear','','danger')}${button('Cancel','close')}</div>`);
 else if(a==='confirm-clear'){if($('#clear-confirm').value!=='CLEAR'){toast('Type CLEAR to confirm');return;}try{await dbOp('readwrite',s=>s.clear());localStorage.removeItem(KEY);state=initial();route='home';location.hash='home';render();toast('Local case and original files cleared');}catch(e){toast('Could not clear all data: '+e.message);}}
 else if(window.RW_WORKSPACES?.handle){window.RW_WORKSPACES.handle(a,state,{esc,field,area,select,check,save,render,toast});}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();Promise.resolve(action(el)).catch(err=>{toast('Could not complete action: '+err.message);});}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='global-search'){$('#global-results').innerHTML=searchResults(el.value);return;}if(el.id==='response-search'){responseTerm=el.value;$('#response-results').innerHTML=responseResults();return;}if(share)return;if(el.dataset.field){set(el.dataset.field,el.type==='checkbox'?el.checked:el.value);save();}});
document.addEventListener('change',async e=>{const el=e.target;if(share)return;
 if(el.dataset.field){set(el.dataset.field,el.type==='checkbox'?el.checked:el.value);save();if(el.type==='checkbox'||el.tagName==='SELECT')render();}
 if(el.dataset.compare){const ids=get('compare.ids')||[];set('compare.ids',el.checked?[...new Set([...ids,el.dataset.compare])]:ids.filter(i=>i!==el.dataset.compare));save();render();}
 if(el.id==='backup-file'&&el.files[0]){try{const f=el.files[0];if(f.size>10*1024*1024)throw Error('Backup exceeds 10 MB.');action.pendingImport=validBackup(JSON.parse(await f.text()));overlay(`<h1>Restore this backup?</h1><p class="muted spaced">This replaces the current case with ${action.pendingImport.log.length} meeting events and ${action.pendingImport.evidence.length} evidence rows. Attached originals already on this device stay available. Export the current case first if needed.</p><div class="row spaced">${button('Export current case','export-json')}${button('Restore backup','confirm-import','','primary')}${button('Cancel','close')}</div>`);}catch(err){toast('Import failed: '+err.message);}}
 if(el.id==='original-file'&&el.files[0]){try{const f=el.files[0];if(f.size>30*1024*1024)throw Error('Choose a file smaller than 30 MB.');const id=uid();await dbOp('readwrite',s=>s.put({id,file:f}));state.attachments.push({id,name:f.name,size:f.size,added:new Date().toISOString()});audit('Attached original locally: '+f.name);save();render();toast('Original saved on this device');}catch(err){toast('Attachment failed: '+err.message);}}
});
document.addEventListener('submit',e=>{if(e.target.id==='quick-form'){e.preventDefault();responseTerm=new FormData(e.target).get('query')||'';location.hash='responses';}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='s'){e.preventDefault();share=true;render();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'){closeOverlay();$('#sidebar')?.classList.remove('open');}if(e.key==='Tab'&&$('#overlay [role="dialog"]')){const nodes=[...$('#overlay').querySelectorAll('button,a,input,select,textarea,summary,[tabindex="0"]')].filter(el=>el.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function preparePrint(){document.querySelectorAll('.print-value').forEach(e=>e.remove());document.querySelectorAll('textarea,input:not([type=checkbox]):not([type=file]),select').forEach(el=>{if(el.closest('#overlay'))return;const value=document.createElement('div');value.className='print-value longtext';value.textContent=el.tagName==='SELECT'?el.options[el.selectedIndex]?.text||'':el.value;el.classList.add('print-hidden');el.insertAdjacentElement('afterend',value);});}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',()=>{document.querySelectorAll('.print-value').forEach(e=>e.remove());document.querySelectorAll('.print-hidden').forEach(e=>e.classList.remove('print-hidden'));});
window.addEventListener('hashchange',()=>{if(share){render();return;}route=location.hash.slice(1).split('?')[0]||'home';render();window.scrollTo(0,0);});
window.addEventListener('online',updateOffline);window.addEventListener('offline',updateOffline);
route=location.hash.slice(1).split('?')[0]||'home';render();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async r=>{await navigator.serviceWorker.ready;updateOffline();r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='activated')updateOffline();});});}).catch(()=>updateOffline());
})();
